from __future__ import annotations

from datetime import datetime, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query

NOW = datetime(2025, 6, 1, 12, 0, 0, tzinfo=timezone.utc)


def _task(id: int, title: str = "task", **kwargs) -> Task:
    defaults = {
        "status": TaskStatus.PENDING,
        "priority": TaskPriority.MEDIUM,
        "created_at": datetime(2025, 1, id, tzinfo=timezone.utc),
    }
    defaults.update(kwargs)
    return Task(id=id, title=title, **defaults)


@pytest.fixture
def tasks():
    return [
        _task(1, "Buy groceries", tags=[Tag("home")], priority=TaskPriority.HIGH),
        _task(2, "Write report", tags=[Tag("work")], priority=TaskPriority.MEDIUM),
        _task(3, "Call dentist", status=TaskStatus.DONE, priority=TaskPriority.LOW),
        _task(4, "Plan vacation", tags=[Tag("home"), Tag("fun")], due_at=datetime(2025, 5, 1, tzinfo=timezone.utc)),
        _task(5, "Read book", due_at=datetime(2026, 1, 1, tzinfo=timezone.utc)),
    ]


class TestFilterStatus:
    def test_filter_pending(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.PENDING), NOW)
        assert all(t.status == TaskStatus.PENDING for t in page.items)
        assert page.total == 4

    def test_filter_done(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.DONE), NOW)
        assert page.total == 1
        assert page.items[0].id == 3


class TestFilterTag:
    def test_filter_by_tag(self, tasks):
        page = apply_query(tasks, TaskQuery(tag="home"), NOW)
        assert page.total == 2
        assert {t.id for t in page.items} == {1, 4}

    def test_tag_normalized(self, tasks):
        page = apply_query(tasks, TaskQuery(tag="  HOME  "), NOW)
        assert page.total == 2


class TestFilterSearch:
    def test_case_insensitive(self, tasks):
        page = apply_query(tasks, TaskQuery(search="buy"), NOW)
        assert page.total == 1
        assert page.items[0].id == 1

    def test_partial_match(self, tasks):
        page = apply_query(tasks, TaskQuery(search="report"), NOW)
        assert page.total == 1

    def test_whitespace_only_ignored(self, tasks):
        page = apply_query(tasks, TaskQuery(search="   "), NOW)
        assert page.total == 5


class TestFilterOverdue:
    def test_overdue_true(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=True), NOW)
        # Task 4 has due_at in the past and is pending
        assert page.total == 1
        assert page.items[0].id == 4

    def test_overdue_false(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=False), NOW)
        # All non-overdue pending tasks (1, 2, 5) plus done task 3
        assert 4 not in [t.id for t in page.items]


class TestSort:
    def test_sort_by_title(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="title"), NOW)
        titles = [t.title for t in page.items]
        assert titles == sorted(titles, key=str.lower)

    def test_sort_by_title_descending(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="title", descending=True), NOW)
        titles = [t.title for t in page.items]
        assert titles == sorted(titles, key=str.lower, reverse=True)

    def test_sort_by_priority(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="priority"), NOW)
        priorities = [t.priority for t in page.items]
        keys = [TaskPriority.order_key(p) for p in priorities]
        assert keys == sorted(keys)

    def test_sort_by_created_at(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="created_at"), NOW)
        dates = [t.created_at for t in page.items]
        assert dates == sorted(dates)

    def test_sort_by_due_at(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="due_at"), NOW)
        # Tasks without due_at sort last
        last_items = page.items[-3:]
        assert all(t.due_at is None for t in last_items)


class TestPagination:
    def test_limit(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=2), NOW)
        assert len(page.items) == 2
        assert page.total == 5
        assert page.has_more is True

    def test_offset(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=2, offset=3), NOW)
        assert len(page.items) == 2
        assert page.offset == 3
        assert page.has_more is False

    def test_offset_beyond_total(self, tasks):
        page = apply_query(tasks, TaskQuery(offset=100), NOW)
        assert page.items == []
        assert page.total == 5
        assert page.has_more is False


class TestTaskQueryValidation:
    def test_invalid_sort_field(self):
        with pytest.raises(TaskQueryError, match="sort must be"):
            TaskQuery(sort="invalid")

    def test_invalid_limit_zero(self):
        with pytest.raises(TaskQueryError, match="limit"):
            TaskQuery(limit=0)

    def test_invalid_limit_too_large(self):
        with pytest.raises(TaskQueryError, match="limit"):
            TaskQuery(limit=101)

    def test_negative_offset(self):
        with pytest.raises(TaskQueryError, match="offset"):
            TaskQuery(offset=-1)

    def test_invalid_tag(self):
        with pytest.raises((TaskQueryError, ValueError)):
            TaskQuery(tag="bad tag!")
